always @(posedge clk or negedge rst_n) begin
    if(!rst_n) begin
        wb_a_byte_equal<=4'b1111; wb_a_byte_less<=0;
        wb_b_byte_equal<=4'b1111; wb_b_byte_less<=0;
    end else begin
        for(wb_compare_byte=0;wb_compare_byte<4;wb_compare_byte=wb_compare_byte+1) begin
            wb_a_byte_equal[wb_compare_byte]<=compare_next_a[wb_compare_byte*8+:8]==compare_next_wb[wb_compare_byte*8+:8];
            wb_a_byte_less[wb_compare_byte]<=compare_next_a[wb_compare_byte*8+:8]<compare_next_wb[wb_compare_byte*8+:8];
            wb_b_byte_equal[wb_compare_byte]<=compare_next_wb[wb_compare_byte*8+:8]==compare_next_b[wb_compare_byte*8+:8];
            wb_b_byte_less[wb_compare_byte]<=compare_next_wb[wb_compare_byte*8+:8]<compare_next_b[wb_compare_byte*8+:8];
        end
    end
end
