        compare_next_wb[wb_relation_byte*8+:8]<id_operand_b[wb_relation_byte*8+:8]};
    assign wb_hold_relations[wb_relation_byte*4+:4]={
        compare_next_a[wb_relation_byte*8+:8]==compare_next_wb[wb_relation_byte*8+:8],
        compare_next_a[wb_relation_byte*8+:8]<compare_next_wb[wb_relation_byte*8+:8],
