    end else begin
        for(wb_compare_byte=0;wb_compare_byte<4;wb_compare_byte=wb_compare_byte+1) begin
            if(id_fire)
                {wb_a_byte_equal[wb_compare_byte],wb_a_byte_less[wb_compare_byte],wb_b_byte_equal[wb_compare_byte],wb_b_byte_less[wb_compare_byte]}<=wb_id_relations[wb_compare_byte*4+:4];
            else
                {wb_a_byte_equal[wb_compare_byte],wb_a_byte_less[wb_compare_byte],wb_b_byte_equal[wb_compare_byte],wb_b_byte_less[wb_compare_byte]}<=wb_hold_relations[wb_compare_byte*4+:4];
        end
    end
end
